{
  "title": "真实模型链路验收",
  "summary": "三大陆修士逐道求存，叩探界门隐秘。",
  "unresolvedQuestions": [
    {
      "id": "uq_01",
      "question": "界门背后是否连通域外天魔族群？",
      "blocking": false,
      "status": "deferred"
    },
    {
      "id": "uq_02",
      "question": "寿元燃尽后是否存在真灵转生之法？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_03",
      "question": "三大陆界门开启时是否会触发天地灵气守恒律的反向大吞噬？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_04",
      "question": "大乾天朝皇室命修是否秘密掌握借国运转移燃寿反噬之法？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_05",
      "question": "补天阁阁主本尊是否早已突破破虚境迈入主宰境？",
      "blocking": false,
      "status": "deferred"
    },
    {
      "id": "uq_06",
      "question": "未来高阶成长仍须遵守灵泉仅增未来寿储、不治疗道伤或返还已付晋阶/燃寿成本的规则；实际可得来源与疗程尚需逐层设计。",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_07",
      "question": "虚空神晶若被大量采集，是否会导致苍冥大陆虚空裂隙提前扩大并崩塌？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_08",
      "question": "太古界门破虚匙共有几柄，补天阁内部是否封存有另外的钥匙残片？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_09",
      "question": "十年前青玄极天界门的无故灵震是否由主角家族或某位通天境强者的秘密燃寿破门引发？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_10",
      "question": "影杀阁乾都刺杀案幕后真凶是否为大乾内部企图夺嫡并推翻宗门妥协路线的皇子？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "audit-power-opening",
      "question": "旧正文开篇燃寿越阶问题仍未改写；当前1–32章替换提案不发动真解，33–100宏观也不发动。须在新章纲、正文及事件一致后复核；不得把旧燃寿额与新提案下界混账。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-resource-definitions",
      "question": "已补充绝命死息 res_15、诸天通宝 res_16 的资源提案并修正势力引用；新增品阶、材质、发行与保存规则尚需对照正文核验，不能视为已确立事实。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-travel-rules",
      "question": "新宏观采用北航五日、返航六日、14,000枚专项款及有时限的外港担保，尚待逐章落地。旧稿打点、火晶换舱和第55章信物均不作为新版实际支付或准入依据；历史保留待对照。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-tier-exceptions",
      "question": "旧稿越阶施术与神器使用仍待替换正文修复。新版百章玄府、赵仍玄府，不采用破虚杀主宰或通天禁术反噬的旧结局；原世界各阶门槛与成本完全保留，后续450章高阶成长仍需有来源。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-resource-usage",
      "question": "资源使用规则为新提案，必须内容复核并重算各章收入/支出。灵泉终生上限30年不能支撑旧第28章神海突破及早期燃寿；历史正文未改，不得倒填已经饮用或凭未来库存先花寿元。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-first-volume-foundation",
      "question": "当前世界的分区、寿储诊断与凝元三重规则仍为提案；已有1–32章替换章纲和33–100宏观，但需分项内容复核与逐章生成，不视新诊断、修炼、药程为已采纳事实。",
      "blocking": true,
      "status": "open"
    }
  ]
}

